class Penter():
    def __init__(self,number:int=1):
        self.name=0
        self.number=number
        print("Penter good guy initing",number)

    @property
    def next(self):
        self.child=Penter((self.number)+1)
        return self.child
a_human=Penter(1)

class Bad_guy():
    def __init__(self,number:int=1):
        print("initing",number)
        self.next=Bad_guy(number+1)
a_stupid_human=Bad_guy()

