# break：立刻跳出整個迴圈
for i in range(10):
    if i == 5:
        break       # 到 5 就停
    print(i)        # 0, 1, 2, 3, 4

# continue：跳過這次，繼續下一次
for i in range(10):
    if i % 2 == 0:
        continue    # 跳過偶數
    print(i)        # 1, 3, 5, 7, 9

fruits = ["apple", "banana", "cherry"]

# 不用 enumerate
for i in range(len(fruits)):
    print(f"{i}: {fruits[i]}")

# 用 enumerate（更 Pythonic）
for i, fruit in enumerate(fruits):
    print(f"{i}: {fruit}")

# 指定起始 index
for i, fruit in enumerate(fruits, start=1):
    print(f"{i}: {fruit}")    # 1: apple, 2: banana, ...

# else 區塊會在迴圈「正常結束」時執行
# 如果被 break 跳出，else 不會執行

for i in range(5):
    if i == 10:    # 不會觸發
        break
else:
    print("迴圈正常結束")    # 會印出

for i in range(5):
    if i == 3:
        break
else:
    print("迴圈正常結束")    # 不會印出（被 break 了）

