# Dict Comprehension
squares = {x: x**2 for x in range(5)}
# {0: 0, 1: 1, 2: 4, 3: 9, 4: 16}

a = {1, 2, 3, 4, 5}
b = {4, 5, 6, 7, 8}

# 聯集 Union（全部合在一起）
print(a | b)                  # {1, 2, 3, 4, 5, 6, 7, 8}
print(a.union(b))             # 同上

# 交集 Intersection（共同的）
print(a & b)                  # {4, 5}
print(a.intersection(b))      # 同上

# 差集 Difference（在 a 但不在 b）
print(a - b)                  # {1, 2, 3}
print(a.difference(b))        # 同上

# 對稱差集 Symmetric Difference（不共同的）
print(a ^ b)                  # {1, 2, 3, 6, 7, 8}
print(a.symmetric_difference(b))  # 同上

a = {1, 2, 3}
b = {1, 2, 3, 4, 5}
c = {1, 2, 3}

# 子集 Subset
print(a.issubset(b))       # True    a 是 b 的子集
print(a <= b)              # True    同上
print(a < b)               # True    真子集（a != b）

# 超集 Superset
print(b.issuperset(a))     # True    b 是 a 的超集
print(b >= a)              # True    同上

# 不相交 Disjoint
print({1, 2}.isdisjoint({3, 4}))   # True   沒有共同元素
print({1, 2}.isdisjoint({2, 3}))   # False  有共同元素 2

